# Reviewed under AGENTS.md
"""Sort semantic version strings by SemVer 2.0.0 precedence."""

from __future__ import annotations

import re

__all__ = ['sort_versions']

_VERSION_RE = re.compile(
    r'(?P<major>0|[1-9]\d*)\.(?P<minor>0|[1-9]\d*)\.(?P<patch>0|[1-9]\d*)'
    r'(?:-(?P<prerelease>(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)'
    r'(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?'
    r'(?:\+[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*)?'
)

# Sort key for pre-release identifiers: numeric identifiers sort before
# alphanumeric ones, so numbers get a lower discriminator.
_IdentifierKey = tuple[int, int | str]


def _parse(version: str) -> tuple[int, int, int, tuple[_IdentifierKey, ...] | None]:
    match = _VERSION_RE.fullmatch(version)
    if match is None:
        raise ValueError(f'invalid semantic version: {version!r}')
    prerelease = match.group('prerelease')
    identifiers: tuple[_IdentifierKey, ...] | None = None
    if prerelease is not None:
        identifiers = tuple(
            (0, int(identifier)) if identifier.isdigit() else (1, identifier)
            for identifier in prerelease.split('.')
        )
    return (
        int(match.group('major')),
        int(match.group('minor')),
        int(match.group('patch')),
        identifiers,
    )


def _sort_key(version: str) -> tuple[object, ...]:
    major, minor, patch, identifiers = _parse(version)
    if identifiers is None:
        # A version without a pre-release is higher than the same version with one.
        return (major, minor, patch, 1)
    # Python compares tuples lexicographically, so a shorter identifier list that
    # shares a prefix with a longer one sorts first, as SemVer requires.
    return (major, minor, patch, 0, identifiers)


def sort_versions(vs: list[str]) -> list[str]:
    """Return ``vs`` sorted by SemVer 2.0.0 precedence, lowest first.

    Build metadata is ignored for ordering, and versions that tie keep their
    input order.
    """
    return sorted(vs, key=_sort_key)
